const authorityCodes = new Set(["authentication_required", "permission_required", "resource_not_found"]);
const lostReasons = [["budget", "Budget"], ["timing", "Timing"], ["no_decision", "No decision"], ["competitor", "Competitor"], ["needs_mismatch", "Needs mismatch"], ["other", "Other"]] as const;
const endpoint = (workspaceId: string, suffix: string) => `/api/workspaces/${workspaceId}/${suffix}`;
const dealPath = (dealId?: string) => `/crm/deals${dealId ? `/${dealId}` : ""}`;
export type SalesErrorDisposition = "authority_loss" | "stale" | "retry_same_request" | "new_request";
export function salesErrorDisposition(error: SalesError): SalesErrorDisposition {
  if (authorityCodes.has(error.code)) return "authority_loss";
  if (error.code === "stale_version" || error.reconciliation.action === "refetch_deal" || error.reconciliation.action === "refetch_pipeline") return "stale";
  return error.reconciliation.action === "retry_same_request" ? "retry_same_request" : "new_request";
}
async function json(response: Response): Promise<unknown> { try { return await response.json(); } catch { return null; } }
