async function csrf() { const response = await fetch("/api/auth/csrf", { cache: "no-store" }); if (!response.ok) throw { code: "authentication_required", message: "Sign in again before continuing.", retryable: false, reconciliation: { required: false, action: "none" } } satisfies SalesError; return (await response.json() as { token: string }).token; }
function keyFor(body: string, current: { body: string; key: string }) { return body === current.body ? current : { body, key: crypto.randomUUID() }; }
const partyLabel = (party: SalesDealSummary["company"]) => party === null ? "None" : party.available ? party.label : "Unavailable";
const outcomeTone = (outcome: SalesDealSummary["outcomeClass"]) => outcome === "won" ? "success" as const : outcome === "lost" ? "danger" as const : "accent" as const;

function SafeSalesState({ error, title = "Deals unavailable" }: { error?: SalesError | null; title?: string }) {
  const login = `/login?next=${encodeURIComponent("/crm/deals")}`;
  return <FeedbackState tone="danger" autoFocus title={title} action={<ActionLink href={error?.code === "authentication_required" ? login : "/crm/deals"}>{error?.code === "authentication_required" ? "Sign in again" : "Back to Deals"}</ActionLink>}><p>Your authority changed or this information is no longer available. Protected Deal, party, value, option, action, and draft data has been cleared.</p></FeedbackState>;
}

function Modal({ titleId, descriptionId, restoreFocus, onClose, children }: { titleId: string; descriptionId: string; restoreFocus: () => void; onClose: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDialogElement>(null), restore = useRef(restoreFocus);
  useEffect(() => { restore.current = restoreFocus; }, [restoreFocus]);
  useEffect(() => { const node = ref.current; if (!node) return; node.showModal(); node.querySelector<HTMLElement>("button")?.focus(); return () => { if (node.open) node.close(); restore.current(); }; }, []);
  return <dialog ref={ref} className="lead-management-dialog" aria-labelledby={titleId} aria-describedby={descriptionId} onCancel={event => { event.preventDefault(); onClose(); }}>{children}</dialog>;
}

